'use client';

import { api } from '@repo/backend/convex/_generated/api';
import confetti from 'canvas-confetti';
import { useMutation, useQuery } from 'convex/react';
import { Sparkle } from 'lucide-react';
import { useRef, useState } from 'react';
import { toast } from 'sonner';

import { FadeInView } from '@/components/animations/FadeInView';
import {
  StaggerChildren,
  StaggerItem,
} from '@/components/animations/StaggerChildren';
import { Button } from '@/components/ui/button';
import { ButtonGroup } from '@/components/ui/button-group';
import { Field } from '@/components/ui/field';
import { GridPattern } from '@/components/ui/grid-pattern';
import { Input } from '@/components/ui/input';
import { Spinner as LoadingSpinner, Spinner } from '@/components/ui/spinner';
import {
  scaleInVariants,
  slideFromLeftVariants,
  slideFromRightVariants,
} from '@/lib/animation-config';

export default function WaitingList() {
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // NOTE: Query real-time stats from Convex
  const premiumStats = useQuery(api.waitlist.getPremiumStats);
  const waitlistCount = useQuery(api.waitlist.getWaitlistCount) ?? 0;

  // NOTE: Exaggerated waitlist count for social proof (easy to adjust)
  const MULTIPLIER = 300;
  const exaggeratedCount = (waitlistCount + 1) * MULTIPLIER;

  const mutateEmail = useMutation(api.waitlist.addEmailToWaitlist);

  // NOTE: Fire confetti when registration succeeds
  const fireConfetti = () => {
    const duration = 3000;
    const end = Date.now() + duration;

    const frame = () => {
      confetti({
        particleCount: 3,
        angle: 60,
        spread: 55,
        origin: { x: 0 },
        colors: ['#22d3ee', '#34d399', '#fbbf24'],
      });
      confetti({
        particleCount: 3,
        angle: 120,
        spread: 55,
        origin: { x: 1 },
        colors: ['#22d3ee', '#34d399', '#fbbf24'],
      });

      if (Date.now() < end) {
        requestAnimationFrame(frame);
      }
    };

    frame();
  };

  const handleRegister = async () => {
    if (!email.trim()) {
      toast.error('Please enter an email', { position: 'bottom-center' });
      return;
    }

    setIsLoading(true);

    try {
      await mutateEmail({ email: email.trim() });
      toast.success(
        'Check your inbox for the magic link to confirm and claim your lifetime premium!',
        { position: 'bottom-center' }
      );
      setEmail('');
      fireConfetti();
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to register email';
      toast.error(errorMessage, { position: 'bottom-center' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !isLoading) {
      handleRegister();
    }
  };

  return (
    <section
      id="waitlist"
      className="relative flex h-screen w-full flex-col items-center justify-center overflow-hidden bg-black-1 px-4 py-12 sm:px-4 lg:px-12"
    >
      <GridPattern
        width={30}
        height={30}
        strokeColor="rgba(255,255,255, 0.3)"
      />
      <div className="relative z-10 flex h-full w-full flex-col overflow-hidden rounded-4xl bg-black-2 p-2 shadow sm:flex-row lg:p-0">
        {/* NOTE: "JOIN THE LIST!" words slide in from alternating sides */}
        <div className="hidden flex-col gap-2 lg:flex lg:gap-4">
          <FadeInView
            variants={slideFromLeftVariants}
            className="justify-baseline flex items-center overflow-hidden"
          >
            <h1 className="font-[nippo] font-bold text-[15vw] leading-none tracking-tighter sm:text-[12vw] lg:text-[20vw]">
              JOIN
            </h1>
          </FadeInView>
          <FadeInView
            variants={slideFromRightVariants}
            delay={0.15}
            className="justify-baseline flex items-center overflow-hidden"
          >
            <h1 className="font-[nippo] font-bold text-[15vw] leading-none tracking-tighter sm:text-[12vw] lg:text-[20vw]">
              THE
            </h1>
          </FadeInView>
          <FadeInView
            variants={slideFromLeftVariants}
            delay={0.3}
            className="justify-baseline sm:justify-baseline flex items-center overflow-hidden"
          >
            <h1 className="font-[nippo] font-bold text-[15vw] leading-none tracking-tighter sm:text-[12vw] lg:text-[20vw]">
              LIST
            </h1>
          </FadeInView>
        </div>

        <div className="flex grow flex-col items-center justify-center gap-4 p-4">
          {/* NOTE: Benefit callout scales in on scroll */}
          <FadeInView variants={scaleInVariants} className="flex flex-2 grow">
            <div className="flex flex-2 grow rounded-4xl bg-green-1 p-4">
              <div
                style={{ opacity: 0.45 }}
                className="flex h-full w-full flex-2 items-start justify-center rounded-4xl bg-black p-4"
              >
                <h1 className="text-4xl text-white md:text-6xl">
                  <span>
                    <Sparkle className="size-12" />
                  </span>
                  First 100 people to sign up on the waitlist will recieve
                  LIFETIME premium membership
                </h1>
              </div>
            </div>
          </FadeInView>

          {/* NOTE: Stats and form with new layout */}
          <StaggerChildren
            staggerDelay={0.15}
            initialDelay={0.3}
            className="flex h-auto w-full flex-1 flex-col items-center justify-between gap-4 rounded-4xl border-2 bg-black-2 p-6 shadow-2xl"
          >
            {/* NOTE: Stats Row - 2 stats side-by-side, always horizontal */}
            <StaggerItem className="flex w-full flex-1 items-center justify-center">
              <div className="flex w-full flex-row items-center justify-center gap-6 sm:gap-10">
                {/* Stat 1: X/100 Premiums Claimed */}
                <div className="flex flex-col items-center justify-center text-center">
                  {premiumStats === undefined ? (
                    <LoadingSpinner className="size-10 text-green-1 sm:size-16" />
                  ) : (
                    <>
                      <span className="font-[nippo] font-bold text-2xl text-white sm:text-5xl lg:text-8xl 2xl:text-9xl">
                        {premiumStats.claimed}/100
                      </span>
                      <span className="font-medium text-[10px] text-white/40 uppercase tracking-widest sm:text-sm">
                        Premiums Claimed
                      </span>
                    </>
                  )}
                </div>

                {/* Separator */}
                <div className="h-12 w-px shrink-0 bg-white/20 sm:h-16" />

                {/* Stat 2: X People Waiting */}
                <div className="flex flex-col items-center justify-center text-center">
                  {premiumStats === undefined ? (
                    <LoadingSpinner className="size-10 text-green-1 sm:size-16" />
                  ) : (
                    <>
                      <span className="font-[nippo] font-bold text-2xl text-white sm:text-5xl lg:text-8xl 2xl:text-9xl">
                        {exaggeratedCount.toLocaleString()}
                      </span>
                      <span className="font-medium text-[10px] text-white/40 uppercase tracking-widest sm:text-sm">
                        Waiting
                      </span>
                    </>
                  )}
                </div>
              </div>
            </StaggerItem>

            {/* NOTE: Email input form - full width */}
            <StaggerItem className="flex h-full w-full items-end justify-center">
              <Field className="w-full">
                <ButtonGroup className="gap-2">
                  <Input
                    ref={inputRef}
                    id="input-button-group"
                    type="email"
                    placeholder="Enter your email"
                    className="h-12 rounded-4xl px-4"
                    value={email}
                    onChange={(event) => setEmail(event.target.value)}
                    onKeyPress={handleKeyPress}
                    disabled={isLoading}
                  />
                  <Button
                    onClick={handleRegister}
                    className="h-12 rounded-4xl bg-green-1 px-4"
                    disabled={isLoading}
                  >
                    {isLoading && <Spinner data-icon="inline-start" />}
                    {isLoading ? 'Registering...' : 'Register'}
                  </Button>
                </ButtonGroup>
              </Field>
            </StaggerItem>
          </StaggerChildren>
        </div>
      </div>
    </section>
  );
}
